/**
 * Initial curated seed — common + professional English.
 *
 * Phase 1B ships with ~60 well-formed entries so the SRS loop can be
 * tested immediately. The full 5000-word frequency list + pro lexicon
 * will be layered on in a later sub-phase (via Mistral generation or
 * a public domain wordlist import) — no change needed to the loader.
 *
 * Rules followed for every entry:
 *   - `lemma` matches exactly the tokens used inside `examples[].en`
 *     (case-insensitive), so the fill-in-the-blank module can blank it.
 *   - At least 2 examples per word for varied recall contexts.
 *   - French (`fr`) is used ONLY in error explanations (immersion goal).
 */

